window.K3_QRAW.push.apply(window.K3_QRAW, [
  {"id": "kc|edu-principle|ep-01|知识点二|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 3, "q": "要求保障“每一个人一无论是儿童、青年还是成人，都应能获益于旨在满足其基本学习需要的受教育机会”，并提出通过提供广泛的学习机会以促进教育和整个社会的平等。这体现了（　）", "opts": ["教育全民化", "教育国际化", "教育现代化", "教育智能化"], "a": 0, "exp": "此题考查教育全民化。教育全民化是指人人都享有平等的受教育的权利，必须接受一定程度的教育。题干中的“每一个人”“无论是儿童、青年还是成人”与教育全民化的概念相符。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}},
  {"id": "kc|edu-principle|ep-01|知识点二|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 4, "q": "1906年，我国清末学部奏请颁布“教育宗旨”；民国之后，我国正式改“学部”为“教育部”。由此可见，我国教育现代化和传统教育学实现转换的一个标志是（）中国古代教育思想中，“教”与“育”的侧重点不同，如《学记》提出的“教学相长”中的“教”，《说文解字》阐释的“育，养子使作善也”中的“育”。其中，“教”更强调（　）", "opts": ["自然生长与潜移默化", "外在规范与主动引导", "家庭环境的熏陶作用", "个体自发的内在觉醒"], "a": 1, "exp": "此题考查教育的含义。在《学记》提出的“教学相长”中，“教”强调教育者主动引导学生掌握知识和技能，带有明确的目的性和指导性，它侧重通过言传、示范等方式，将社会规范、伦理道德、知识体系传递给受教育者，具有主动性、外显性和规范性的特点。《说文解字》将“育”解释为“养子使作善也”，侧重滋养成长。A.自然生长与潜移默化：属于“育”的侧重点，而非“教”的侧重点。B.外在规范与主动引导：“教学相长”的“教”侧重教育者的主动引导与规范。√C.家庭环境的熏陶作用：更多与“育”的含义中家庭教养的影响相关。D.个体自发的内在觉醒：强调个体主动性，与“教”的外在引导属性不符。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}},
  {"id": "kc|edu-principle|ep-01|知识点二|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 5, "q": "以下现象属于教育范畴的是（　）", "opts": ["小明不小心被火灼伤，由此知道火是热的", "妈妈指导小明发生火灾时如何逃生", "盗窃团队教给新成员盗窃技巧", "学校严格管理引火物品，使其远离学生"], "a": 1, "exp": "此题考查教育的本质。教育是一种有目的、有意识地培养人的社会活动。A.小明偶然通过自身体验获得认知，这个过程缺少教育者的引导和传授，缺乏教育的目的性，属于偶然获得生活经验，不属于教育。B.妈妈作为教育者，教会小明逃生技巧，这个过程属于教育。√C.盗窃团伙教给成员技巧是为了进行违法犯罪活动，这不符合教育促使人向好发展的特点。D.学校严格管理引火物品属于一种管理，不涉及对学生的教育。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}},
  {"id": "kc|edu-principle|ep-01|知识点二|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 6, "q": "小丁不怎么懂得拒绝别人。有一天，小丁和爸爸正高兴地打着羽毛球，小红过来说也要玩。小丁把球拍让给了小红，可是一脸不情愿的样子。回家的路上，爸爸对小丁说：“你如果还想玩，可以对小红说，我再玩一会儿就给你。”这一案例反映了家庭教育的哪一特点？（　）", "opts": ["家庭教育是培育人才的起点和基石", "家庭教育具有相机而教的特点", "父母应该给予孩子高质量的陪伴", "家庭教育具有很强的情感性"], "a": 1, "exp": "此题考查家庭教育。四个选项的说法都是正确的，但是只有B选项与题干内容相匹配。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}},
  {"id": "kc|edu-principle|ep-01|知识点二|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 7, "q": "下列属于家庭教育范畴的是（　）", "opts": ["妈妈给不能自主进食的幼儿喂饭", "小明将抄袭的作文拿去参加比赛，妈妈告诉他做人要诚实", "某些山村里，有些父亲认为女孩无用，不让女儿继续读书", "小张的妈妈给小张报了金牌培训班补习功课"], "a": 1, "exp": "此题考查家庭教育。A选项是抚养行为。B选项，妈妈对小明进行诚实教育，属于家庭教育。C选项，父亲因为陈旧的观念阻止女孩接受教育，这种行为是家庭教育的绊脚石。D选项，小张的妈妈只是给孩子报了补习班，并没有对小张进行教育。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}},
  {"id": "kc|edu-principle|ep-01|知识点二|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 8, "q": "以下关于非正规教育的说法，错误的是（　）", "opts": ["非正规教育是无组织、无计划的教育活动，与正规教育形成对比", "非正规教育是促进终身学习的重要手段", "非正规教育需要政府的大力引导和规范", "非正规教育对建设学习型社会具有重大的积极意义"], "a": 0, "exp": "此题考查非正规教育。非正规教育是在正规教育系统外进行的有组织、有计划的教育活动。此题为选非题，因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 132}},
  {"id": "kc|edu-principle|ep-01|知识点二|9", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 9, "q": "我国提倡残障儿童接受和普通儿童一样的教育，这体现了（）的教育理念。（　）", "opts": ["全民教育", "融合教育", "补偿教育", "生命教育"], "a": 1, "exp": "此题考查融合教育。A.全民教育：每个人都应获得旨在满足其基本学习需要的受教育机会，人人都必须接受一定程度的教育。B.融合教育：让大多数残障儿童进人普通班，并促进其在普通班的学习。√C.补偿教育：泛指国家或社会为保障处境不利群体接受合格教育所采取的各种补偿措施或行动的总和。D.生命教育：引导学生认识、尊重和珍爱生命，促进学生积极地提升生命质量，实现生命的意义和价值。（说明：融合教育、补偿教育等专业词汇在往年真题中出现过，考生需要理解这些词汇的含义。）", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点二|10", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 10, "q": "教育公平的实现需要多维度政策支持。下列措施中，最能体现系统性教育公平理念的是（　）", "opts": ["学区优化、师资流动、特殊教育补贴", "数字化教学、国际课程引进、研学旅行", "重点班设置、学科竞赛培养、天才教育计划", "民办教育扶持、海外分校建设、双语教学推广"], "a": 0, "exp": "此题考查中国特色社会主义教育发展与改革。A.学区优化（资源分配）、师资流动（机会均衡）特殊教育补贴（弱势补偿）共同构成了教育公平的完整支持体系，全面体现了系统性教育公平理念。√B.数字化教学、国际课程引进、研学旅行体现了教育的现代化，未涉及教育公平的核心问题。C.重点班设置、学科竞赛培养、天才教育计划均属于精英教育模式，会人为拉大不同学生群体间的差距，与教育公平理念相。D.民办教育扶持是为了促进办学主体多元化，增加教育事业的活力；海外分校建设和双语教学推广则体现了教育国际化。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点二|11", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点二：教育的含义及相关概念", "no": 11, "q": "以下符合“随班就读”所涉及的实践议题的是（　）", "opts": ["全纳教育、全民教育、融合教育", "国际理解教育、补偿教育、民主教育", "全纳教育、多元文化教育、融合教育", "多元文化教育、全民教育、补偿教育"], "a": 0, "exp": "此题考查教育热点词汇。“随班就读”原本是指让部分肢残、轻度弱智、弱视和重听等残障孩子进人普通班就读进行教育的一种方式，其目的就是要让这些特殊孩子能够与普通学生一起活动、相互交往的同时，获得必要的有针对性的特殊教育和服务，以及必要的康复和补偿训练，以便使这些孩子能够更好地融入社会。这与国际理解教育、多元文化教育无关。补偿教育是指为处境不利者或受正规教育失败者提供可供选择的、补充的教育，以帮助他们获得社会就业能力，与“随班就读”不匹配。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点三|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点三：教育的结构与要素", "no": 1, "q": "从形式上说，教育活动方式不包括（　）", "opts": ["教学内容", "教育手段", "教育方法", "教育组织形式"], "a": 0, "exp": "此题考查教育活动方式。教育活动方式是指教育者引导受教育者学习教育内容所选用的交互活动方式，主要指教育手段、教育方法、教育组织形式等，不包括教学内容。此题为选非题，·因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点三|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点三：教育的结构与要素", "no": 2, "q": "下列教育活动的基本要素中，具有主体性地位的是（　）", "opts": ["学习者", "教育者", "教育活动方式", "教育内容"], "a": 0, "exp": "此题考查教育活动的基本要素。在教育活动的四要素中，教育者起主导作用，受教育者（也称学习者）起主体作用，教育内容是精神客体，教育活动方式是中介桥梁。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点三|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点三：教育的结构与要素", "no": 3, "q": "下列选项中，关于教育活动四要素之一的教育内容的说法，正确的是（　）", "opts": ["教育内容指课本知识，不包括实践活动", "教育内容是教育者向受教育者传授的知识、技能和价值观的总和", "教育内容由教师决定，不受社会、文化或学生需求影响", "教育内容的核心是考试大纲，一切教学都应围绕考试展开"], "a": 1, "exp": "此题考查教育内容。A.修改：教育内容并非局限于课本知识，教师精心设计的实践活动同样属于教育内容。B.教育内容是教育者向受教育者传授的知识、技能、价值观等，涵盖学科知识、实践活动、道德教育等多个方面，即直接经验和间接经验。√C.修改：教育内容受社会、文化、学生、教师等多方面因素影响。D.修改：考试只是评价手段，并非教学的根本目的。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点四|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点四：教育功能", "no": 1, "q": "教育成为个体生活的需要，受教育的过程是需要满足的过程，这是指教育的（　）", "opts": ["个体谋生功能", "个体享用功能", "个体个性化功能", "个体社会化功能"], "a": 1, "exp": "此题考查教育的个体享用功能。A.个体谋生功能：个体通过教育获得生存技能和知识以维持生计。：B.个体享用功能：教育能使个体的精神生活得到满足，使个体获得自由和幸福。√C.个体个性化功能：教育促使个体形成独特的个性和自主能力。D.个体社会化功能：教育帮助个体学习社会规范、价值观等，使个体更好地融人社会。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点四|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点四：教育功能", "no": 2, "q": "在发展中国家，义务教育的普及显著提高了国民识字率，为工业化提供了合格劳动力。这一事实最能体现教育的（　）", "opts": ["经济导向的显性功能", "政治导向的显性功能", "政治导向的隐性功能", "经济导向的隐性功能"], "a": 0, "exp": "此题考查教育的功能。A.“在发展中国家，义务教育的普及显著提高了国民识字率，为工业化提供了合格劳动力”不仅是教育促进经济发展的表现，也是教育按照预设目的发展所达成的结果，体现了教育的经济导向的显性功能。√B.题干没有体现教育对政治的作用。C.题干没有体现教育对政治的作用，也没有体现教育的隐性功能。D.“为工业化提供了合格劳动力”主要体现的是教育对经济的作用。通过提高国民识字率来促进经济发展，是有目共睹的、预期性的目的，体现的是教育的显性功能。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点四|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点四：教育功能", "no": 3, "q": "教育的本体功能之一是（　）", "opts": ["减少人口数量，提高人口素质", "促进生产发展，服务经济建设", "对政治、经济有巨大的影响与作用", "加速年轻一代的身心发展与社会化进程"], "a": 3, "exp": "此题考查教育的本体功能。教育的本体功能即教育的个体发展功能，是指教育对个体生存和发展的影响和作用，主要体现为个体个性化功能、社会化功能、谋生功能、享用功能。A、B、C选项是教育的社会发展功能。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点四|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点四：教育功能", "no": 4, "q": "高收入家庭可以将部分收入投人到下一代的教育中来积累学历优势、技能优势，使其下一代优于收人较低家庭出生的孩子。长此以往，社会流动性下降，阶层逐渐固化，对国家造成的破坏将是毁灭性的。这段话体现了教育的（　）", "opts": ["社会显性负向功能", "社会隐性负向功能", "个体显性负向功能", "个体隐性负向功能"], "a": 1, "exp": "此题考查教育的功能。社会流动性下降，阶层逐渐固化，体现了教育的社会负向功能。因为这种负向功能并不能直接被人察觉，也不是教育直接造成的，所以是社会隐性负向功能。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 133}},
  {"id": "kc|edu-principle|ep-01|知识点四|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点四：教育功能", "no": 5, "q": "光明小学建立学校表扬制度，每周选出道德、学业以及其他各项活动中表现突出的学生将其事迹张贴在表扬专栏中，这不仅激发了学生的学习热情，与此同时竟然也增强了学生对学校的归属感。这属于（　）", "opts": ["正向显性功能和正向隐性功能", "正向隐性功能和负向隐性功能", "负向显性功能和正向隐性功能", "负向隐性功能和正向显性功能"], "a": 0, "exp": "此题考查教育的功能。学生对学校的归属感”，“竟然”说明这是没有预料到的，体现了正向隐性功能。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点四|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点四：教育功能", "no": 6, "q": "有学者说：“教育的所作所为都在促使人在现存体制的利益驱动下，在各种被社会化了的欲望支配下，在体制为他所规定的轨道上，不停地走，不停地走，教育只是在使人变成一头被蒙上眼的推磨驴子。”这段话所论述的内容体现了教育的（　）", "opts": ["个体发展的正向功能", "个体发展的负向功能", "社会发展的正向功能", "社会发展的负向功能"], "a": 1, "exp": "此题考查教育的功能。负向功能体现在“教育只是在使人变成一头被蒙上眼的推磨驴子”，这句话在批判教育不顾及学生个性的发展，而是束缚学生的思想。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点五|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点五：教育的起源与发展", "no": 1, "q": "“教育是与种族需要、种族生活相适应的、天性的，而不是获得的表现形式；教育既无须周密的考虑使它产生，也无须科学予以指导，它是扎根于本能的不可避免的行为。”这种教育起源说属于（　）", "opts": ["社会起源说", "生物起源说", "心理起源说", "劳动起源说"], "a": 1, "exp": "此题考查生物起源说。教育起源说总结表名称观点生物起源说教育的产生完全来自动物本能，是种族发展的本能需要原始教育的形式和方法主要是日常生活中儿童对成人生活的无意识模仿心理起源说劳动起源说（社会起源说）教育源于劳动和劳动过程中所产生的需要，是人类特有的一种社会活动生物起源说认为，教育的产生完全来自动物本能，是种族发展的本能需要。题干中有明显的“种族需要”字眼。由此可知，题干描述的是生物起源说。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点五|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点五：教育的起源与发展", "no": 2, "q": "认为原始教育的形式和方法主要是日常生活中儿童对成人生活的无意识模仿，这一学说是（　）", "opts": ["社会起源说", "生物起源说", "心理起源说", "劳动起源说"], "a": 2, "exp": "此题考查心理起源说。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点五|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点五：教育的起源与发展", "no": 3, "q": "下列属于马克思主义教育起源说的是（　）", "opts": ["劳动起源说", "生物起源说", "心理起源说", "神话起源说"], "a": 0, "exp": "此题考查劳动起源说。马克思主义教育起源说认为，人类教育起源于劳动和劳动过程中所产生的需要。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点五|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点五：教育的起源与发展", "no": 4, "q": "下列属于原始社会教育特征的是（　）", "opts": ["系统性", "制度性", "无阶级性", "阶级性"], "a": 2, "exp": "此题考查教育的发展。原始社会时期，教育制度尚未形成，因此不具有系统性、制度性和阶级性。阶级性是古代社会的学校教育的特点，教育目的是培养统治人才。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点五|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点五：教育的起源与发展", "no": 5, "q": "我国唐代中央官学设有“六学一馆”，其人学条件中明文规定不同级别官员的子孙进人不同的学校。这主要体现了我国封建社会教育制度的（　）", "opts": ["继承性", "等级性", "历史性", "民族性"], "a": 1, "exp": "此题考查教育的发展。“不同级别官员的子孙进人不同的学校”体现了封建社会的学校教育具有等级性。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点五|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点五：教育的起源与发展", "no": 6, "q": "以下有关现代教育特征的描述，不正确的是（　）", "opts": ["人的全面发展的思想从理论走向现实", "教育结构日趋稳定，变革速度减慢", "教育民主化向纵深发展", "教育终身化"], "a": 1, "exp": "此题考查现代教育的特征。A、C、D选项均正确。现代教育具有从实际行动中重视全面发展、教育民主化向纵深发展、教育终身化的特点。现代教育变革的速度在加快，而不是减慢。此题为选非题，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点五|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点五：教育的起源与发展", "no": 7, "q": "教育与人类社会共始终，为一切人、一切社会所必需，是新生一代的成长和社会生活的延续与发展不可缺少的手段。这句话未说明教育的（　）", "opts": ["阶级性", "历史性", "永恒性", "社会性"], "a": 0, "exp": "此题考查教育的发展。教育与社会共存、共延续，反映了教育的永恒性和历史性；同时，二者由此产生的紧密联系也体现了教育的社会性，但没有体现阶级性。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-01|知识点五|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-01", "chName": "第一章 教育及其产生与发展", "sec": "知识点五：教育的起源与发展", "no": 8, "q": "以下关于心理起源说的说法，正确的是（　）", "opts": ["勒图尔诺说明了人的模仿与动物的本能活动的差别", "认为人是有心理活动的，但它忽视了人的教育的有意识性", "主张教育起源于儿童对成人生活的有意识模仿", "标志着在教育起源的问题上开始从神话解释转向科学解释"], "a": 1, "exp": "此题考查心理起源说。A.修改：勒图尔诺是生物起源说的代表人物。此外，心理起源说从本质上并没有说明人的模仿与动物的本能活动的差别。B.心理起源说认为人是有心理活动的，但它忽视了人的教育的有意识性。√C.修改：心理起源说主张教育起源于日常生活中儿童对成人生活的模仿，这种模仿是无意识性的，从根本上抹杀了教育的有意识性。D.修改：生物起源说标志着在教育的起源问题上开始从神话解释转向科学解释。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 134}},
  {"id": "kc|edu-principle|ep-02|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 1, "q": "莱布尼茨曾说：“如果给我以教育的全权，不需要一百年，就可以使欧洲改观。”这一说法体现了（　）", "opts": ["筛选假设理论", "教育万能论", "人力资本论", "劳动力市场理论"], "a": 1, "exp": "此题考查教育万能论。教育与社会关系的主要理论总结表主要理论代表人物核心观点教育独立论蔡元培教育经费独立；教育行政独立；教育内容独立；教育脱离宗教而独立爱尔维修教育万能论人的成长归因于教育与环境；人的发展完全是由教育决定的人力资本是促进个体发展和社会发展的重要因素，所以国家要重视教育投人力资本论舒尔茨资对人力资本的作用教育并不能提高一个人的能力，却能表征一个人的能力。教育水平是反映迈克尔·斯宾塞筛选假设理论一个人能力高低的有效信号，是雇主鉴定求职者能力、筛选求职者的工具劳动力市场理论皮奥雷、多林格、戈登教育是决定个体进人哪种劳动力市场的重要因素之一教育系统控制着文化资本的生产、传递和转换，是支配社会地位、形成社布尔迪厄再生产理论会无意识的重要体制，也是再生产不平等社会结构的主要手段以促进社会发展，但是用词都不激进；题干中莱布尼茨的话语是激进的，认为仅靠教育就可以改变欧洲，因此一直被看作教育万能论的经典论据。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 135}},
  {"id": "kc|edu-principle|ep-02|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 2, "q": "教育可以实现个人能力的提高，进而促进经济的增长。这种观点属于（　）", "opts": ["人力资本论", "筛选假设理论", "劳动力市场理论", "教育万能论"], "a": 0, "exp": "此题考查人力资本论。人力资本论认为，教育能够提升劳动者的知识和技能，知识和技能可以转化为劳动者的人力资本，对社会经济的发展起到促进作用。依据知识点一第1题解析，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 135}},
  {"id": "kc|edu-principle|ep-02|知识点一|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 3, "q": "（）是从分析劳动力市场上雇主选聘求职者的过程去说明教育的经济价值的。（　）", "opts": ["教育万能论", "人力资本论", "筛选假设理论", "劳动力市场理论"], "a": 2, "exp": "此题考查筛选假设理论。筛选假设理论主张教育具有筛选的功能，是用来区别不同人的能力的手段，主要作用是帮助雇主识别能力不同的求职者。依据知识点一第1题解析，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 135}},
  {"id": "kc|edu-principle|ep-02|知识点一|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 4, "q": "“教育并不能提高人的能力，教育只是一个筛子，是用来区别不同人的能力的手段。”“人受了什么样的教育，就成为什么样的人。”以上两种观点分别属于（　）", "opts": ["劳动力市场理论、教育万能论", "劳动力市场理论、教育独立论", "筛选假设理论、教育万能论", "筛选假设理论、教育独立论"], "a": 2, "exp": "此题考查教育与社会关系的理论。筛选假设理论认为，教育并不能提高人的能力，教育只是一个筛子，是用来区别不同人的能力的手段，教育具有筛选的功能。教育万能论认为，人的成长归因于教育与环境，“人受了什么样的教育，就成为什么样的人”。题干中两种观点分别属于筛选假设理论和教育万能论。依据知识点一第1题解析，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 135}},
  {"id": "kc|edu-principle|ep-02|知识点一|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 5, "q": "党的十八大报告提出要不断健全现代市场体系，但我国长期以来实行固定工、临时工、合同工等多种用工制度并存的形式，实际上为劳动力贴上了不同的身份标签，这并不会增加社会成员的工作流动性。从教育与社会关系的角度分析，其理论基础是（　）", "opts": ["教育独立论", "劳动力市场理论", "教育万能论", "人力资本论"], "a": 1, "exp": "此题考查劳动力市场理论。劳动力市场理论认为，一个人的工资水平主要取决于他在主要劳动力市场还是在次要劳动力市场工作，教育只是决定一个人在哪一个劳动力市场工作的重要因素之一，两个劳动力市场具有封闭性。依据知识点一第1题解析，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 135}},
  {"id": "kc|edu-principle|ep-02|知识点一|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 6, "q": "（　）认为，教育系统控制着文化资本的生产、传递和转换，是支配社会地位、形成社会无意识的重要体制，也是再生产不平等社会结构的主要手段。（　）", "opts": ["人力资本论", "筛选假设理论", "劳动力市场理论", "再生产理论"], "a": 3, "exp": "此题考查再生产理论。布尔迪厄认为，教育系统控制着文化资本的生产、传递和转换，是支配社会地位、形成社会无意识的析，因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 135}},
  {"id": "kc|edu-principle|ep-02|知识点一|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 7, "q": "起套课程公众号【研大］深联系微信193163788日关于教育与社会关系的主要理论的描述，正确的是（　）", "opts": ["人力资本论主张教育只能表征而不能提高人的能力", "筛选假设理论认为教育与个人收入不呈正相关", "劳动力市场理论认为信号和标识能表明一个人的生产能力", "再生产理论主张学校的教育行为是一种符号暴力"], "a": 3, "exp": "此题考查教育与社会关系的主要理论。A.修改：人力资本论注重教育投资的作用，主张教育能提升劳动者的知识和技能。B.修改：筛选假设理论认为教育与个人收入呈正相关。C.修改：筛选假设理论认为信号和标识能表明一个人的生产能力。D.再生产理论主张学校的教育行为是一种符号暴力。√", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 135}},
  {"id": "kc|edu-principle|ep-02|知识点一|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 8, "q": "下列不属于对人力资本论的评价的是（　）", "opts": ["教育能提高一个人的能力，然后根据能力得到相应的工资", "未考虑到劳动力市场的分类", "否认了正规教育的优势", "揭示了教育与经济的关系"], "a": 2, "exp": "此题考查人力资本论。人力资本投资包括学校教育、职业教育等多种形式，并没有否认正规教育的优势。此题为选非题，依", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 136}},
  {"id": "kc|edu-principle|ep-02|知识点一|9", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 9, "q": "以下不属于教育相对独立性的表现的是（　）", "opts": ["教育具有自身发展的继承性和发展性", "教育与政治、经济、文化的发展不同步", "教育内容的选择受制于社会发展需要", "教育对社会的作用具有能动性"], "a": 2, "exp": "C理解题此题考查教育的相对独立性。C选项表明了教育的社会制约性，不是相对独立性的表现。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 136}},
  {"id": "kc|edu-principle|ep-02|知识点一|10", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点一：教育与社会关系的理论", "no": 10, "q": "某研究发现，在控制家庭背景因素后，名校毕业生与普通院校毕业生的收人差距显著缩小；但若按照行业划分，高收人行业（如金融、科技）中的名校效应依然显著。下列理论中，最能解释这一现象的是（　）", "opts": ["人力资本论", "再生产理论", "劳动力市场理论", "筛选假设理论"], "a": 2, "exp": "此题考查劳动力市场理论。A.人力资本论：认为教育能提升个体的知识和技能（人力资本），从而提高生产力和收入。该理论无法解释“收入差距因控制家庭背景因素而缩小”的现象，排除。B.再生产理论：认为教育通过筛选、分层，再生产现有的社会阶级结构。题干中“控制家庭背景因素”，其实是弱化了阶层再生产的直接影响，排除。C.劳动力市场理论：将劳动力市场划分为主要劳动力市场（高收入、稳定行业）和次要劳动力市场（低收入、不稳定行业）。主要劳动力市场更看重名校标签，次要劳动力市场更关注技能。这解释了控制家庭背景因素后，整体收入差距会缩小，但高收入行业中的名校效应依然显著的现象。√D.筛选假设理论：认为教育是“信号筛选”工具，名校作为能力信号帮助个体获得高收入。该理论无法解释信号效应仅在高收入行业显著，而在普通行业不显著的现象，排除。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 136}},
  {"id": "kc|edu-principle|ep-02|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点二：教育的社会制约性", "no": 1, "q": "社会对教育事业的需求程度最终取决于（　）", "opts": ["科技水平", "社会制度", "文化背景", "生产力水平"], "a": 3, "exp": "此题考查生产力对教育的影响与制约。生产力的发展水平影响着社会对教育事业的需求程度，也影响着社会对劳动力的需求水平，进而影响着教育事业发展的速度与规模。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 136}},
  {"id": "kc|edu-principle|ep-02|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点二：教育的社会制约性", "no": 2, "q": "当前，发达国家大多普及了10年以上的义务教育，而发展中国家一般仅普及了9年义务教育。这说明从根本上制约教育事业发展的速度和规模的社会因素是（　）", "opts": ["人口的数量和素质", "生产力发展水平", "社会的政治经济制度", "民族传统文化"], "a": 1, "exp": "此题考查教育的社会制约性。生产力发展水平影响着社会对教育事业的需求程度，也影响着社会对劳动力的需求水平，进而影响着2.54教育事业发展的速度和规模。在现代社会中，义务教育的普及与延长是由生产力发展水平决定的。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 136}},
  {"id": "kc|edu-principle|ep-02|知识点二|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点二：教育的社会制约性", "no": 3, "q": "）不是由政治经济制度决定的。下列选项中，（　）", "opts": ["教育的性质", "教学方式", "受教育者的权利", "教育的领导权"], "a": 1, "exp": "此题考查政治经济制度对教育的影响与制约。政治经济制度的性质决定教育性质，影响教育目的，影响教育的领导权、受教育权，影响教育内容、教育结构和教育管理体制，但不包括教学方式。此题为选非题，因此，答案选B。A.错误，题干侧重“教什么”，即教育内容，而非教育方式。B.中国古代的文化价值观是重农抑商、追求仕途，导致教育内容侧重典章制度，轻视自然科学。√C.错误，题干没有体现生产力与教育发展水平的关系。D.错误，题干没有体现生产力与教育领导权的关系。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 136}},
  {"id": "kc|edu-principle|ep-02|知识点二|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点二：教育的社会制约性", "no": 4, "q": "以下关于教育的社会制约性的表述，不正确的是（　）", "opts": ["政治经济制度的性质决定着教育的性质", "生产力的发展水平决定着教育的发展水平", "文化知识影响教育的内容和水平", "人口结构决定着教育结构"], "a": 3, "exp": "此题考查教育的社会制约性。人口结构对教育产生的影响体现在：一方面，人口的年龄结构会影响教育的发展；另一方面，人口的就业结构也会影响教育的发展。人口结构不能决定教育结构。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 136}},
  {"id": "kc|edu-principle|ep-02|知识点二|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点二：教育的社会制约性", "no": 5, "q": "关于媒介对教育发展的制约作用，下列说法正确的是（　）", "opts": ["新媒介技术导致传统教育方式被淘汰", "媒介资源分布不均会加剧教育机会不平等", "教育内容需要完全适应媒介技术的特性", "纸质教材的消亡是媒介发展的结果"], "a": 1, "exp": "此题考查媒介对教育发展的制约作用。A.修改：新媒介技术会冲击传统教育方式，但并未导致其完全淘汰。传统教育中的面对面互动、课堂氛围等优势仍具有不可替代性，实际教学中更多是新老媒介技术的融合共生。B.媒介资源分布不均会使不同群体获取教育资源的机会存在差异，进而加剧教育机会不平等，如偏远地区网络覆盖不足就会制约在线教育的发展。√C.修改：“完全适应”是一个绝对化的表述，教育内容的选择应首先考虑育人目标，媒介只是工具而非主导因素。D.修改：媒介发展确实推动了数字教材的普及，但纸质教材具有便携、无须电子设备支持、适合深度阅读等优点，仍会在一定范围内长期存在，并不会必然消亡。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点二|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点二：教育的社会制约性", "no": 6, "q": "历史老师带领学生戴上VR眼镜“走”进紫禁城，定位系统将他们带到太和殿，AR程序让殿内陈设和历史人物“复活”并进行语音讲解。这说明（　）", "opts": ["科技对教育发展有决定作用", "科学教育能够培养科技人才", "科技发展能够促进教育发展", "科学教育促进科技不断革新"], "a": 2, "exp": "此题考查科技对教育的影响。A.错误，题干只体现新的科技手段可以改进历史教学，对教育起决定性作用的是生产力发展水平。B.错误，题干没有体现科学教育，没有提及培养科技人才。C.科技发展带来VR、AR技术，有效改进了教学方法，提供了丰富的教育资源，提高了学生的学习兴趣，促进了教育发展。√D.错误，题干意思是科技发展促进教育进步，而非通过教育促进科技发展。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点三|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点三：教育的社会功能", "no": 1, "q": "教育是潜在的、间接的生产力，教育成果一般通过受教育者的实际生产活动转化为直接的、物化的生产力。这反映了教育的（　）", "opts": ["超前性", "继承性", "迟效性", "生产性"], "a": 3, "exp": "此题考查教育的生产性。选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点三|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点三：教育的社会功能", "no": 2, "q": "有报道称：“相比目前普通高等教育严峻的就业形势，职业教育就业率这么多年来可以说是一直居高不下，全国中等职业学校毕业生就业率连续5年保持在95%以上，对大部分的职业生来说，毕业即就业..”这体现了职业教育的（　）", "opts": ["政治功能", "经济功能", "文化功能", "科技功能"], "a": 1, "exp": "此题考查教育的功能。职业教育传授专门的知识和技能，提高人的劳动能力，使其能够在生产中直接运用高科技，并且进行技术创新。题干中的报道体现了职业教育的经济功能。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点三|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点三：教育的社会功能", "no": 3, "q": "在现代学校，世界各国都有开设政治类和思想品德类的课程，如“社会课”“品德课”等。下列不属于其背后的深层次原因的是（　）", "opts": ["让学生了解国家的方方面面", "培养国家需要的合格公民", "教育为政治服务", "为培养统治人才打好基础"], "a": 0, "exp": "此题考查教育的政治功能。世界各国的学校开展政治教育，是为了发挥教育的政治功能。教育的政治功能主要体现在教育能维系深联系微信19316378日日社会政治稳定、提高社会政治文明水平、促进社会政治变革、培养社会政治人才。A选项不属于深层次原因。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点三|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点三：教育的社会功能", "no": 4, "q": "《礼记·学记》中的“古之王者建国君民，教学为先”体现了（　）", "opts": ["教育的经济功能", "教育的政治功能", "教育的文化功能", "教育的人口功能"], "a": 1, "exp": "此题考查教育的政治功能。“古之王者建国君民，教学为先”意为：古代的君王在建立国家、统治民众时都把教育放在首要位置。这充分表明了教育是治国安邦的关键，体现了教育的政治功能。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点三|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点三：教育的社会功能", "no": 5, "q": "人口学家的研究结果显示：全体国民受教育程度的高低与人口出生率的高低成反比。这说明了（　）", "opts": ["教育可以影响人口数量", "教育可以提高人口质量", "教育可以改善人口结构", "教育可以促进人口迁移"], "a": 0, "exp": "此题考查教育的人口功能。随着家庭受教育程度的普遍提升，改变了人们传统的“多子多福”“人丁兴旺”的观念。于是，教育反过来起到了控制人口增长的作用。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点三|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点三：教育的社会功能", "no": 6, "q": "杜威认为：“文化过分庞杂，不能全部吸收，必须通过教育‘简化”，吸收其基本内容·为了使人们避免他所在社会群体的文化局限，必须通过教育来‘平衡”社会文化中的各种成分，以便和更广阔的文化建立充满生机的联系。”这体现了文化的（）功能。（　）", "opts": ["传承与融合", "创新与选择", "选择与融合", "传承与创新"], "a": 2, "exp": "此题考查教育的文化功能。“文化过分庞杂，不能全部吸收..”，因此，文化需要通过教育来“简化”，这体现了文化的选择功能。“为了使人们避免他所在社会群体的文化局限，必须通过教育来‘平衡”社会文化中的各种成分，以便和更广阔的文化建立充满生机的联系”体现了教育的文化融合功能。因此，答案选C。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点三|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点三：教育的社会功能", "no": 7, "q": "以下不属于教育的生态功能的是（　）", "opts": ["教育能够引导建设生态文明的社会活动", "教育能够促使生态系统的承载能力不断提高", "教育能够普及生态文明知识，提高民族素质", "教育能够逐步在全社会牢固树立建设生态文明的理念"], "a": 1, "exp": "此题考查教育的生态功能。A、C、D选项均属于教育的生态功能。B选项，生态系统的承载能力是生态系统自身具有的一种有限的自我调节能力，教育在一定程度上可以通过提高人口素质等方法提高生态系统的承载能力，但当人口数量超出最大负荷量，调节便会失效。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 137}},
  {"id": "kc|edu-principle|ep-02|知识点四|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点四：当代社会发展对教育的需求与挑战", "no": 1, "q": "注重课程的时代性和稳定性的统一、结构性和系统性的统一，加强学科之间的相互渗透，调整必修课和选修课的比例，引进科技发展的新成就、新理论。这体现了教育现代化的哪种特点？（　）", "opts": ["教师素质现代化·", "教育观念现代化", "教育内容现代化", "教育制度现代化"], "a": 2, "exp": "此题考查教育现代化。A.教师素质现代化：包括教师的思想观念现代化、职业道德素质现代化、知识构成现代化和教育能力现代化。B.教育观念现代化：摒弃与时代和社会发展相背离的、落后的教育观，树立与现代社会发展需要相一致的教育观念。C.教育内容现代化：注重课程的导向，加强学科间的渗透，引进新的理论，体现了通过教育内容的调整推进教育现代化。√D.教育制度现代化：建立高质、高效的教育管理体制；坚持开放、民主的教育管理原则；使用融合现代管理技术的教育管理手段。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 138}},
  {"id": "kc|edu-principle|ep-02|知识点四|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点四：当代社会发展对教育的需求与挑战", "no": 2, "q": "教育现代化是整个社会现代化进程中不可或缺的一部分。其中，教育现代化的关键是教师素质的现代化。下列选项中不属于教师素质现代化的表现的是（　）", "opts": ["坚持“以生为本”“以学为本”的教育发展观", "积极掌握多元化知识", "教育教学中驾驭信息技术的素养", "下放教育管理权"], "a": 3, "exp": "此题考查教师素质的现代化。教师素质的现代化包括教师的思想观念现代化、职业道德素质现代化、知识构成现代化和教育能力现代化，并不包含下放教育管理权。此题为选非题，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 138}},
  {"id": "kc|edu-principle|ep-02|知识点四|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点四：当代社会发展对教育的需求与挑战", "no": 3, "q": "随着“汉语热”持续升温和中国文化在全球影响力的不断增强，孔子学院开到了全世界许多国家，为各国学员学习中文、了解中国文化提供帮助，为增进人文交流、促进世界和谐和多元化发展做出了重要贡献。这体现了（　）", "opts": ["教育国际化", "教育现代化", "教育本土化", "教育民族化"], "a": 0, "exp": "此题考查教育国际化。教育国际化是指以国际的视野和全球认同的方式，构建教育发展和运行的完整体系和管理制度。题干中，孔子学院传播中国文化，体现了教育国际化。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 138}},
  {"id": "kc|edu-principle|ep-02|知识点四|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点四：当代社会发展对教育的需求与挑战", "no": 4, "q": "有几十年教龄的张老师在一次教师分享会上感概，教师职业不同以往了。以前在上课时，他觉得自己是教室中知识最丰富的人，现在却总有需要向学生请教的时候，比如视频如何播放、某同学口中的网络用语是什么意思等，这让他很不习惯，课余时间也总想学习些什么。张老师的感概最能体现的是（　）", "opts": ["教育科学化", "教育制度化", "教育终身化", "教育全民化"], "a": 2, "exp": "此题考查教育终身化。唯一渠道。所以，互联网时代客观上更容易促使师生关系平等化，进而促进教师终身学习。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 138}},
  {"id": "kc|edu-principle|ep-02|知识点四|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点四：当代社会发展对教育的需求与挑战", "no": 5, "q": "从传统讲授到慕课与在线教育，再到“人工智能+教育”，这一系列转变的核心是（　）", "opts": ["培养目标的变革．", "教育管理的变革．", "教育方式的变革", "教育制度的变革"], "a": 2, "exp": "此题考查信息社会与教育变革。A.培养目标的变革：聚焦“培养什么样的人”，如在信息社会背景下，教育要培养具有较高信息素养的人。B.教育管理的变革：主要表现在改变学校的管理方式、改变国家对整个教育事业的管理方式，促使教育管理向数据化、便捷化、智能化的方向发展。C.教育方式的变革：“人工智能+教育”进一步引入智能技术，如自适应学习系统、虚拟助教、沉浸式教学场景等，实现个性化、智能化的教学交互。以上均围绕“如何教、如何学”展开，属于教育方式（教学手段、学习模式）的变革。√D.教育制度的变革：涉及学制、考试制度等结构性调整（如终身教育体系）。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 138}},
  {"id": "kc|edu-principle|ep-02|知识点四|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-02", "chName": "第二章 教育与社会发展", "sec": "知识点四：当代社会发展对教育的需求与挑战", "no": 6, "q": "人工智能是引领新一轮科技革命的核心技术，也是教育现代化的重要驱动力。推动人工智能赋能教育强国建设应坚持的基本原则是（）：（　）", "opts": ["①②③④", "①②③", "①③④", "②③④"], "a": 0, "exp": "此题考查人工智能与教育。此题考生常会在A、D选项之间犹豫：判断出②③④属于人工智能赋能教育强国建设是相对容易的，而不论发展哪种类型的教育，都必须立德树人。故人工智能教育也需要守住立德树人的基本线，①是成立的。因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 138}},
  {"id": "kc|edu-principle|ep-03|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点一：人的身心发展的特点", "no": 1, "q": "在相同的阶段里，同一个体身心的各方面发展速度有快有慢，存在巨大的差异性，这里指的是身心发展的（　）", "opts": ["顺序性", "阶段性", "不平衡性", "差异性"], "a": 2, "exp": "此题考查人的身心发展的不平衡性。人的身心发展特点总结表特点含义差异性由于遗传、环境及教育等因素的不同，不同个体之间身心发展存在着个别差异不平衡性同一个体在不同的年龄阶段，身心发展不均衡；在同一时期，身心不同方面的发展也不均衡人的身心发展要遵循一定的方向性和先后顺序顺序性阶段性个体发展的不同阶段会表现出不同的年龄特征及主要矛盾，面临着不同的发展任务因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 139}},
  {"id": "kc|edu-principle|ep-03|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点一：人的身心发展的特点", "no": 2, "q": "大脑皮层的发展为枕叶→题叶→顶叶一额叶，脑细胞的发育为轴突一树突→轴突的髓鞘化。这体现了人的身心发展具有（　）", "opts": ["顺序性", "阶段性", "不平衡性", "差异性"], "a": 0, "exp": "此题考查人的身心发展的特点。识点一第1题解析，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 139}},
  {"id": "kc|edu-principle|ep-03|知识点一|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点一：人的身心发展的特点", "no": 3, "q": "在某个时期内，个体对某种刺激特别敏感，过了这个时期，同样的刺激则对其影响很小或没有影响。这个时期被称为（　）", "opts": ["关键期", "发展期", "转折期", "潜伏期"], "a": 0, "exp": "此题考查人的身心发展的关键期。A.关键期：对特定技能或行为模式发展最敏感的时期或者应做准备的时期，只有在这个时期，个体发育过程中的某些行为在适当的环境刺激下才会出现。如果在这个时期缺少适当的环境刺激，这种行为便不会再得到良好的发展。√B.发展期：个体发展的每一阶段都可称作发展期，与个体敏感的时期无关。C.转折期：强调心理发展发生急剧变化的时期，与个体敏感的时期无关。D.潜伏期：弗洛伊德人格发展理论中性冲动暂时潜伏的阶段，与个体敏感的时期无关。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 139}},
  {"id": "kc|edu-principle|ep-03|知识点一|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点一：人的身心发展的特点", "no": 4, "q": "走班制学生依据自已的课表进人不同班级听课，这是对传统的以班级为单位的行政班授课制的重大突破。从本质上说，这遵循了学生身心发展的（　）", "opts": ["阶段性", "差异性", "不平衡性", "顺序性"], "a": 1, "exp": "此题考查人的身心发展的特点。走班制的本质是尊重每个学生的发展差异，使每个学生都能够得到最好的发展。这遵循了学生身心发展的差异性。依据知识点一第1题解析，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 139}},
  {"id": "kc|edu-principle|ep-03|知识点一|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点一：人的身心发展的特点", "no": 5, "q": "对残疾儿童进行教育的重要依据之一是（　）", "opts": ["儿童身心发展具有顺序性", "儿童身心发展具有不平衡性", "儿童身心发展具有个别差异性", "儿童身心发展具有分化与互补的协调性"], "a": 3, "exp": "理解+积累题此题考查人的身心发展的协调性。儿童身心发展的“分化与互补的协调性”使个体能够在某一机能缺失时，通过其他机能的代偿与协调，仍能实现残疾儿童的整体发展，与顺序性、不平衡性或个别差异性无关。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 139}},
  {"id": "kc|edu-principle|ep-03|知识点一|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点一：人的身心发展的特点", "no": 6, "q": "研究者让不同年龄段的儿童阅读关于合作行为的故事，并谈谈自己的看法。结果显示：学前儿童仅知谁参与了合作；小学低年级儿童能理解合作是为完成任务，但不懂分工；小学中年级儿童明白合作需分工，并能初步分析合作成功或失败的原因；小学高年级儿童能从团队和社会发展层面阐述合作价值。在不同的合作群体中，儿童的合作方式、合作能力、合作意识都各有不同。这表明儿童对合作行为的认知发展具有（　）", "opts": ["顺序性、整体性、阶段性", "阶段性、顺序性、差异性", "顺序性、不平衡性、互补性", "差异性、整体性、不平衡性"], "a": 1, "exp": "此题考查人的身心发展的特点。（1）儿童在不同年龄阶段对合作行为的认知表现出明显不同的特点，学前儿童、小学低年级儿童、小（2）从学前儿童仅知谁参与了合作，到小学低年级儿童能理解合作目的，再到小学中年级儿童明白合作需分工，并能初步分析合作成败的原因，最后到小学高年级儿童能从宏观层面阐述合作价值，呈现出从简单到复杂、由浅人深的发展顺序，这体现了儿童认知发展的顺序性。（3）在不同的合作群体中，儿童的合作方式、合作能力、合作意识都各有不同，这体现了儿童认知发展的差异性。（4）整体性是指人的身心的整体发展。题干仅讨论儿童的合作行为，不涉及儿童的整体发展。（5）不平衡性是指同一个体身心各方面的发展是不平衡的。题干讨论的是不同个体的发展，而非同一个体身心各方面的发展。（6）互补性是指个体某种感官存在缺陷时，其他感官可以对其进行补偿和补充。题干描述未体现互补性。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 140}},
  {"id": "kc|edu-principle|ep-03|知识点一|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点一：人的身心发展的特点", "no": 7, "q": "下列句子与其所体现的人的身心发展的特点对应正确的是（　）", "opts": ["当其可之谓时”——顺序性", "深其深，浅其浅，尊其尊，益其益”—阶段性", "不陵节而施之谓孙”——不平衡性", "柴也愚，参也鲁，师也辟”一—差异性"], "a": 3, "exp": "此题考查人的身心发展的特点。A.修改：“当其可之谓时”是指在适当的时机进行教育或行动，体现了人的身心发展的不平衡性。B.修改：“深其深，浅其浅，尊其尊，益其益”是指在教学中用深一点的知识教育程度较深的人，用浅一点的知识教育程度较浅的人，用尊重的态度对待别人的自尊，用使其增长的办法对待人的长处。这体现了因材施教的教学原则，体现了人的身心发展的差异性。C.修改：“不陵节而施之谓孙”是指循序渐进地教学，在教学时不超越学生的接受能力，这体现了人的身心发展的顺序性。D.“柴也愚，参也鲁，师也辟”是指高柴愚直，曾参迟钝，颛孙师偏激。他们都是孔子的学生，对不同的学生采取不同的教育方法，体现了人的身心发展的差异性。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 140}},
  {"id": "kc|edu-principle|ep-03|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点二：影响人的身心发展的因素", "no": 1, "q": "“近朱者赤，近墨者黑”说明了（：·）对人的身心发展有重要的作用。（　）", "opts": ["遗传", "环境·", "学校教育", "个体的主观能动性"], "a": 1, "exp": "此题考查环境对人的身心发展的作用。“近朱者赤，近墨者黑”是指在什么样的环境中就会成长成什么样的人，强调环境对人的身心发展有重要作用。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 140}},
  {"id": "kc|edu-principle|ep-03|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点二：影响人的身心发展的因素", "no": 2, "q": "小明和小红都出生在一个画家家庭，小明从小感受到艺术氛围，自己也喜欢画画，并以画画为业；小红对父母画画司空见惯，毫无兴趣，从不画画。两人的选择截然不同，这最能体现出哪种因素的影响？（　）", "opts": ["遗传", "环境", "个体自身的主观能动性", "学校教育"], "a": 2, "exp": "此题考查影响人的身心发展的因素。出生在画家家庭的孩子可能遗传画画的基因，在日常生活环境中可能会受到影响，但是也有可能毫无兴趣，从不画画，这最能体现个体自身的主观能动性对其的影响。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 140}},
  {"id": "kc|edu-principle|ep-03|知识点二|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点二：影响人的身心发展的因素", "no": 3, "q": "所谓学校教育功能的异化，是指学校教育由促进人的全面发展的工具变成了阻碍人的全面发展的异己力量。以下哪个说法不属于学校教育功能异化的表现？（　）", "opts": ["高效率的班级授课制在压抑学生的个性", "日复一日的学校教育在压抑创造精神", "学校教育自身的合理性与校外的环境等都制约着学校教育主导作用的发挥", "学校教育并没有给予学生想要的快乐的教育，而是形成了苦闷的教育"], "a": 2, "exp": "此题考查学校教育功能的异化。学校教育功能的异化是指学校教育由促进人的全面发展的工具变成了阻碍人的全面发展的异已力量。学校教育自身的合理性与校外的环境等都制约着学校教育主导作用的发挥，这属于影响学校教育主导作用发挥的条件，而非学校教育功能的异化表现。此题为选非题，因此，答案选C。深联系微信193163788日", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 140}},
  {"id": "kc|edu-principle|ep-03|知识点二|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点二：影响人的身心发展的因素", "no": 4, "q": "学校教育的特殊性决定了其在学生个体发展中具有主导作用。需要指出的是，教育主导作用的发挥是有条件的，以下不属于学校教育内部条件的是（　）", "opts": ["学校教育尊重受教育者的主观能动性与身心发展规律", "学校教育的课程设置的合理性、教学方法的有效性", "学校教育应统筹家庭教育、社会教育等各种教育资源", "学校教育要重视教师的素质"], "a": 2, "exp": "此题考查影响学校教育主导作用发挥的条件。C选项属于学校教育的外部条件。此题为选非题，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 140}},
  {"id": "kc|edu-principle|ep-03|知识点二|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点二：影响人的身心发展的因素", "no": 5, "q": "学校教育发挥主导作用，主要表现在促进个体个性化和个体社会化。以下不属于促进个体个性化方面的是（　）", "opts": ["个体学习未来所扮演的职业角色的知识、技能", "人通过创造活动来完善自我", "人是历史的创造者，也是改造自然、改造世界的主人", "个体具有独特的心理特征和心理倾向性"], "a": 0, "exp": "此题考查教育的个体个性化功能。个体个性化是指个体在社会生活中追求独特性、主体性、创造性的过程。个体社会化是指个体接受文化规范，学习其所处社会的行为模式，由一个自然的人转化为社会的人的过程。个体学习未来所扮演的职业角色的知识、技能属于个体社会化的表现。此题为选非题，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 140}},
  {"id": "kc|edu-principle|ep-03|知识点二|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点二：影响人的身心发展的因素", "no": 6, "q": "诸葛亮在《诫子书》中有云：“才须学也，非学无以广才，非志无以成学。”孔子日：“学而不思则罔，思而不学则殆。”这两句话共同体现了影响人的身心发展的因素是（　）", "opts": ["①②", "②③", "①③", "②④"], "a": 1, "exp": "此题考查影响人的身心发展的因素。诸葛亮认为，才能必须通过学习才能拓展，志向是坚持学习的前提。孔子主张学习是获取知识的根本途径，独立思考是消化知识的关键。这两句古文反映的不是环境和遗传对人的身心发展的影响，而是教育和主观能动性对人的身心发展的影响，故②③当选。因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点二|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点二：影响人的身心发展的因素", "no": 7, "q": "某中学通过组织学生参与社区志愿服务、开展“民族团结”主题演讲比赛、制订班级公约等活动，引导学生理解社会角色期待、遵守社会规范。这主要体现了学校教育在促进个体社会化过程中（的功能。（　）", "opts": ["传递科学文化知识，提高个体认知水平", "引导个体遵守社会规范，明确角色责任", "发展个体兴趣特长，促进个性自由发展", "提供社会实践平台，培养个体创新能力"], "a": 1, "exp": "此题考查教育的个体社会化功能。.A.该选项强调“科学文化知识”，与题干中的“理解社会角色期待、遵守社会规范”无关。B.题干中，学校主要通过组织学生参与各种实践活动来帮助其理解社会角色期待、遵守社会规范，并最终促进学生的个体社会化。此过程与该选项描述相符。√D.该选项强调“创新能力”，体现的是教育的个体个性化功能。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点二|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点二：影响人的身心发展的因素", "no": 8, "q": "某研究团队的研究报告显示：A组儿童生活的地区图书馆资源丰富，且会定期举办文化活动；B组儿童生活的地区公共文化设施缺乏，其家长多从事体力劳动，亲子互动时间少，且家长一般不带孩子参加文化活动。五年后，A组儿童在语言表达能力测试中的得分比B组儿童高15%，但两组儿童在数学运算能力上无显著差异。这项研究结果表明（　）", "opts": ["遗传对儿童语言表达能力发展的作用更明显", "环境对儿童数学运算能力的发展不起作用", "丰富的文化资源环境能促进儿童语言表达能力的发展", "主观能动性在儿童身心发展中起决定作用"], "a": 2, "exp": "此题考查影响人的身心发展的因素。A.题干未提及遗传对儿童语言表达能力发展的影响。B.两组儿童在数学运算能力上无显著差异，并不能说明环境对儿童数学运算能力的发展不起作用，可能是其他因素导致该方面没有体现出差异。该选项的说法过于绝对。C.题干体现出丰富的文化资源环境能促进儿童语言表达能力的发展。√D.题干未提及主观能动性对儿童身心发展的影响。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点三|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点三：影响人的身心发展的理论", "no": 1, "q": "教育决定论属于（　）", "opts": ["单因素论", "多因素论", "内发论", "内因与外因交互作用论"], "a": 0, "exp": "此题考查单因素论。影响人的身心发展因素的主要理论总结表理论观点单因素论只有一个因素对人的身心发展起决定作用，如环境决定论、遗传决定论多因素论影响人的身心发展的因素是多方面的，如成熟论（二因素论）内发论强调人的身心发展的力量主要源于人自身的内在需要，身心发展的顺序也是由身心成熟机制决定的外论人的发展主要依靠外在的力量，诸如环境的刺激和要求、他人的影响与学校的教育等内因与外因交互人的发展是多种因素综合影响的结果，是先天遗传与后天社会影响以及主体在活动中的主观能动性的交互作用的统一作用论教育决定论认为教育这一因素在人的身心发展中起决定作用，属于单因素论。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点三|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点三：影响人的身心发展的理论", "no": 2, "q": "下列关于人的身心发展影响因素的主要观点中，属于内发论的是（　）", "opts": ["自然成熟论", "教育万能论", "环境决定论", "白板说"], "a": 0, "exp": "此题考查内发论。此题可以用排除法作答。教育万能论强调“教育”的作用；环境决定论强调“环境”的作用；“白板说”强调外界对人的身心的塑造。B、C、D选项均是强调外部因素。依据知识点三第1题解析，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点三|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点三：影响人的身心发展的理论", "no": 3, "q": "教育是“园艺艺术”，教师是“园丁”，学生是“祖国的花朵”。这属于（　）", "opts": ["环境决定论", "成熟论", "内因与外因交互作用论", "遗传决定论"], "a": 2, "exp": "此题考查内因与外因交互作用论。我生长的作用，属于内因与外因交互作用论。依据知识点三第1题解析，因此，答案选C。：", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点三|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点三：影响人的身心发展的理论", "no": 4, "q": "古语有云：“人之所不学而能者，其良能也；所不虑而知者，其良知也。”这句话强调的是（　）", "opts": ["外论", "内发论", "多因素论", "内外因交互作用论"], "a": 1, "exp": "此题考查影响人的身心发展因素的主要观点。干中的“不学而能”“不虑而知”说明良知、良能都是人与生俱来的，这是典型的内发论的观点。因此，答案选B。（说明：此题亦可通过推理作答。题干内容是孟子的观点，而孟子的性善论属于内发论。）", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点三|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点三：影响人的身心发展的理论", "no": 5, "q": "“今人之性，生而有好利焉，顺是，故争夺生而辞让亡焉；生而有疾恶焉，顺是，故残贼生而忠信亡焉；生而有耳目之欲，有好声色焉，顺是，故淫乱生而礼义文理亡焉。”这句话体现了（　）", "opts": ["内发论", "外论", "内因与外因交互作用论", "环境决定论"], "a": 1, "exp": "此题考查个体身心发展的动因。若顺其本性发展，必将使社会陷入混乱、抢夺之中，这是十分有害的。因此，他强调外部力量的作用，属于外论的观点。依据知识点三第1题解析，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点三|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点三：影响人的身心发展的理论", "no": 6, "q": "“染于苍则苍，染于黄则黄，所人者变，其色亦变。”“人性之善也，犹水之就下也。人无有不善，水无有不下。”二者的观点分别属于（　）", "opts": ["内发论、外论", "内发论、内发论", "外铄论、外论", "外铄论、内发论"], "a": 3, "exp": "此题考查影响人的身心发展的理论。第一句话是墨子的“素丝说”，强调教育和环境的重要性，属于外论的观点。第二句话是孟子的“性善论”，属于内发论的观点。依据知识点三第1题解析，因此，答案选D。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 141}},
  {"id": "kc|edu-principle|ep-03|知识点三|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-03", "chName": "第三章 教育与人的发展", "sec": "知识点三：影响人的身心发展的理论", "no": 7, "q": "古希腊哲学家柏拉图在《理想国》中提出“金银铜铁”的先天灵魂等级说，认为教育应当根据不同个体天生的灵魂材质实施差异化培养。这一观点最接近（　）", "opts": ["教育万能论", "遗传决定论", "环境决定论", "活动内化论"], "a": 1, "exp": "此题考查影响人的身心发展因素的主要观点。A.教育万能论：夸大了教育在个体发展中的作用，认为教育可以决定人的发展，不符合题意。B.遗传决定论：柏拉图提出“金银铜铁”的先天灵魂等级说，认为教育应当根据不同个体天生的灵魂材质实施差异化培养。这一观点与遗传决定论一样，都突出了先天因素对个体发展的重要性。√C.环境决定论：强调环境对个体发展的主导作用，与柏拉图强调的先天灵魂材质决定个体发展的观点相悖。D.活动内化论：强调个体通过活动将外部的知识、经验等内化为自已的心理结构，不符合题意。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 142}},
  {"id": "kc|edu-principle|ep-04|知识点一|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点一：教育目的概述", "no": 1, "q": "2021年修订的《中华人民共和国教育法》中的教育方针是：“教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合，培养（：：）。”（　）", "opts": ["德智体美全面发展的社会主义建设者和接班人", "德智体美劳全面发展的社会主义建设者和接班人", "德智体全面发展的社会主义建设者和接班人", "德智体美劳全面发展的“四有”新人"], "a": 1, "exp": "此题考查我国的教育方针。2021年新修订的《中华人民共和国教育法》指出：教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合，培养德智体美劳全面发展的社会主义建设者和接班人。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 142}},
  {"id": "kc|edu-principle|ep-04|知识点一|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点一：教育目的概述", "no": 2, "q": "“学生能获得C语言基础、条件、循环、函数等方面的知识，能够熟练阅读和运用结构化程序设计方法进行设计、编写、调试和运行C语言程序。”这项要求属于教育目的的层次结构中的（　）", "opts": ["教育目的", "培养目标", "课程目标", "教学目标"], "a": 2, "exp": "此题考查教育目的的层次结构。的要求，属于课程目标。依据知识点一第2题解析，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点一|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点一：教育目的概述", "no": 3, "q": "教育目的是检查教师教育教学质量的重要依据和评判标准，这最能说明教育目的具有（、（　）", "opts": ["教育评价功能", "控制教育方向的作用", "指导和支配教育活动的作用", "端正教育思想的功能"], "a": 0, "exp": "此题考查教育目的的功能。A.题干中强调“检查教师教育教学质量”说明教育目的最直接的功能是评价功能。√B.侧重教育目的对整个教育事业发展方向的规定和制约，与题干不符。C.侧重教育目的对具体教学安排、内容选择和方法运用的指导和支配，与题干不符。D.侧重教育目的对教育者观念和认识的引导作用，与题干不符。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点一|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点一：教育目的概述", "no": 4, "q": "某师范院校明确提出，要培养具备扎实学科知识、卓越教学能力，且具有创新教育理念和教育研究素养，能够引领基础教育改革发展的优秀教师。上述要求属于教育目的层次结构中的（　）", "opts": ["教育目的", "培养目标", "课程目标", "教学目标"], "a": 1, "exp": "此题考查教育目的的层次结构。目的是国家层面的总体要求，课程目标围绕具体课程展开，教学目标则聚焦课堂教学活动，三者均与题干描述不符。依据知识点一第2题解析，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点一|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点一：教育目的概述", "no": 5, "q": "张老师在《悯农》一课中设置了相关目标，他希望学生能体会到农民劳作的艰辛，理解粮食的来之不易，从而培养他们珍惜粮食的意识和尊重劳动的情感。这里的“目标”属于（　）", "opts": ["培养目标", "课程目标", "教学目标", "教育目的"], "a": 2, "exp": "此题考查教学目标。惜粮食的意识和尊重劳动的情感，这一目标是针对该节课的具体行为要求，属于最微观的“教学目标”。依", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点一|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点一：教育目的概述", "no": 6, "q": "下列不属于我国学校培养目标的演变的是（　）", "opts": ["从四有“新人”到四有“公民", "从“双基”到“三维目标”再到“核心素养", "从片面发展到全面发展", "从培养“劳动者”到培养“建设者和接班人"], "a": 1, "exp": "此题考查培养目标。从“双基”到“三维目标”再到“核心素养”是我国课程目标的变化，不属于学校培养目标的演变。此题为选非题，因此，答案选B。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点一|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点一：教育目的概述", "no": 7, "q": "教育目的不仅反映当时社会的要求，亦蕴含着对未来教育的期望和要求，指向教育的未来。它的特点不包括（　）", "opts": ["预期性", "客观性", "恒定性", "时代性"], "a": 2, "exp": "此题考查教育目的的特点。A.教育目的是社会或个人对受教育者提出的期望和要求，展现的是一种预期的状态。B/D.教育目的具有时代的气息，任何一个教育目的都是在特定的历史客观条件下做出的选择。C.教育目的具有相对稳定性，但并非永恒不变。不同时代的教育目的会因社会条件的变化而调整。此", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点一|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点一：教育目的概述", "no": 8, "q": "下列关于教育目的与教育方针的关系，说法正确的是（　）", "opts": ["教育目的包含教育方针，二者具有内在的一致性", "教育方针与教育目的是目的和手段的关系", "教育方针一般是党提出的，不会改变", "与教育目的相比，教育方针更为侧重“办什么样的教育”“怎样办教育"], "a": 3, "exp": "此题考查教育目的与教育方针的关系。A.修改：教育方针包含教育目的，二者具有内在的一致性。B.修改：教育方针与教育目的是手段和目的的关系。C.修改：教育方针一般是国家或政党提出的，但2015年、2018年我国的教育方针都有所修订。D.与教育目的相比，教育方针更为侧重“办什么样的教育”“怎样办教育”。√", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点二|1", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 1, "q": "个人本位论与社会本位论。涂尔干说：“教育在于使青年社会化，在我们每个人中，造成一个社会的我。这便是教育的目的。”这反映了（　）", "opts": ["教育适应生活说个人本位论法国教育家卢梭认为“儿童的天性和自由”决定教育目的，这种教育目的的价值取向属于（", "社会本位论教育准备生活说·", "国家本位论个人本位论", "社会本位论生活本位论"], "a": 0, "exp": "此题考查个人本位论。教育目的的相关理论总结表相关理论观点教育目的的制定应由受教育者的需要、潜能和个性决定，个人价值高于社会价值个人本位论社会本位论教育目的的制定应该由社会的需要决定，社会价值高于个人价值国家本位论教育目的应以国家利益为出发点和归宿生活本位论把教育目的与受教育者的生活紧密联系在一起文化本位论以文化发展的要求确定教育目的，以文化为内容，根据学生的个性特点进行教育教育适应生活说教育应该为当下儿童的生活做准备，关注儿童发展的切实需要教育准备生活说教育的目的应该为将来生活做准备教育不应局限于当下的生活，而应引领个体超越现实生活教育超越生活说教育改造生活说教育的目的在于改造社会生活，应积极运用教育的力量，推动社会进步教育目的应满足学生内在需要，没有外在目的内在目的论外在目的论政治、社会的要求或教师等人强加给儿童的目的（说明：教育超越生活说与教育改造生活说，国家本位论、生活本位论与文化本位论作为拓展性内容了解即可。）强调“儿童的天性和自由”决定教育目的，考虑儿童的内在生长，属于个人本位论。因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点二|2", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 2, "q": "在儒家文化中，即便是主张“修身”，也不是为了“养性”，而是为了“齐家”“治国”“平天下”。这种文化传统体现了（：．：）的价值取向。（　）", "opts": ["社会本位", "个人本位", "生活本位", "文化本位"], "a": 0, "exp": "此题考查教育目的的价值取向。根据题意，教育最终的落脚点是“齐家”“治国”“平天下”，属于社会本位论。依据知识点二第2题解析，因此，答案选A。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点二|3", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 3, "q": "“社会是铸模，个人是其所要铸造的金子，金子的价值高于铸模。”“宗教信仰、道德信仰与习俗，民族传统的总和就是社会我。塑造社会我，就是教育的目的。”这两句话体现的价值取向分别是（　）", "opts": ["个人本位论、社会本位论深联系微信193163788日", "社会本位论、个人本位论", "生活本位论、社会本位论", "个人本位论、生活本位论"], "a": 0, "exp": "此题考查教育目的的理论。我，就是教育的目的”体现了社会本位论的观点。依据知识点二第2题解析，因此，答案选A。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 143}},
  {"id": "kc|edu-principle|ep-04|知识点二|4", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 4, "q": "关于教育目的的价值取向，以下观点不属于个人本位论的是（　）", "opts": ["卢梭认为“儿童的自然”决定教育目的", "裴斯泰洛齐认为“教育的目的在于发展人的一切天赋力量和能力", "帕克认为“一切教育的真正目的，是人，即人的身体思想和灵魂的和谐发展", "杜威认为“社会是教育的目的，儿童是教育的起点"], "a": 3, "exp": "此题考查教育目的的价值取向。杜威的这句话强调教育的内在目的，但也没有否认教育的社会目的，从他的社会理想一—民主主义可知，教育也要为社会进步服务，为民主制度的完善服务，是实现民主社会的工具。这不属于个人本位论的观点。此题为选非题，因此，答案选D。·教育准备生活说和教育适应生活说。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|5", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 5, "q": "教育准备生活说和教育适应生活说。“教育的目的在于使个人能够继续他们的教育，或者说，学习的目的和报酬是继续不断的生长能力。”持这种观点的人，在教育目的上主张（　）", "opts": ["教育准备生活说", "教育适应生活说", "教育超越生活说", "教育改造生活说"], "a": 1, "exp": "此题考查教育适应生活说。依据儿童的身心发展规律、兴趣与需要进行教育，更好地促进儿童的生长与发展。依据知识点二第2题解析，因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|6", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 6, "q": "在教育史上，重视实科教育，主张学生学习的自觉性，强调教育为完满生活做准备的教育家是（　）", "opts": ["夸美纽斯", "赫尔巴特", "斯宾塞", "杜威"], "a": 2, "exp": "此题考查教育准备生活说。斯宾塞重视实科教育，强调教育为完满生活做准备，主张教育准备生活说。因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|7", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 7, "q": "下列关于教育适应生活说的描述，正确的是（　）", "opts": ["着重体现了教育的过程性和动态性", "核心是培养儿童对知识体系的记忆能力", "强调儿童完全适应成人社会的既有规则", "本质是儿童被动适应外部环境的过程"], "a": 0, "exp": "此题考查教育适应生活说。A.教育适应生活说强调教育是儿童当下生活的过程，而非对未来生活的静态预备。儿童通过与环境的交互作用，不断地改造经验，体现了教育的过程性和动态性。√B.修改：教育适应生活说注重儿童的主动参与和经验的改造，而不是对知识体系的记忆能力。C.修改：教育适应生活说强调教育应该为儿童的当下生活做准备，关注儿童发展的切实需要，而非强调儿童完全适应成人社会的既有规则。D.修改：教育适应生活说认为儿童是主动与环境互动的，而非被动适应外部环境。·内在目的论与外在目的论·", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|8", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 8, "q": "内在目的论与外在目的论。认为“教育目的就是教育本身”的教育家是（　）", "opts": ["卢梭", "裴斯泰洛齐", "夸美纽斯", "杜威"], "a": 3, "exp": "此题考查内在目的论。杜威主张教育内在目的论，认为“教育的过程在它自身以外无目的；它就是它自身的目的”。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|9", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 9, "q": "根据杜威的观点，“培养绅士”“为未来完满的生活做准备”等教育目的都是（　）", "opts": ["内在目的论", "教育适应生活说", "外在目的论", "个人本位论"], "a": 2, "exp": "此题考查外在目的论。杜威认为，“培养绅士”“为未来完满的生活做准备”都是外界对教育的要求，属于外在目的论。杜威否定教育的外在目的。依据知识点二第2题解析，因此，答案选C。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|10", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 10, "q": "以下选项中，体现了教育的内在目的论对教育实践的指导的是（　）", "opts": ["学校教育不应追求明确的目的，而应依据现实灵活安排教育活动", "教师在教学中应关注学生兴趣的激发", "学校教育只为学生的个性自由服务，不需要为社会服务", "在学生的内在生长中不需要追求纪律"], "a": 1, "exp": "此题考查教育的内在目的论。A.该选项是对教育的内在目的论的误解。教育的内在目的论并非否定教育目的，而是强调目的应指向学生的内在发展，而非外在功利性目标。B.兴趣属于内在因素，教师从激发学生兴趣出发进行教学，符合教育的内在目的论中关注个体内在生长的理念。√C.教育的内在目的论虽强调个性自由，但并未完全排斥社会价值，只是反对将社会需求凌驾于学生发展之上。D.教育的内在目的论并不否定纪律，它主张通过内在动机（如自律）实现发展，而非依赖外在强制。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|11", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 11, "q": "关于内在目的与外在目的的关系，下列说法中不正确的是（　）", "opts": ["内在教育目的是外在教育目的在具体教学情境中的具体落实", "外在教育目的总是直接或间接地影响内在教育目的", "在具体实际问题中，外在教育目的可以直接替代内在教育目的", "杜威把教育目的分为教育过程的外在目的和教育过程本身的内在目的"], "a": 2, "exp": "此题考查教育目的的理论。外在目的体现了国家、社会对人才规格的需要，而内在的教育目的强调教育过程本身的价值。所以，一个国家的教育目的不仅要重视教育的内在目的，还要依据教育的外在目的。无论何时，都无法直接用外在教育目的替代内在教育目的。此题为选非题，因此，答案选C。·马克思主义关于人的全面发展学说。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|12", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 12, "q": "马克思主义关于人的全面发展学说。马克思认为造成人的片面发展的根本原因是（　）", "opts": ["个人天赋", "社会分工", "国家性质", "教育水平"], "a": 1, "exp": "此题考查马克思主义关于人的全面发展学说。马克思认为社会分工造成了人的片面发展；生产力的高速发展为人的全面发展提供了物质基础。因此，答案选B。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|13", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 13, "q": "马克思主义关于人的全面发展学说指出，造就全面发展的人的唯一方法是（　）", "opts": ["脑力劳动与体力劳动相结合", "智育与体育相结合", "知识分子与工人农民相结合", "教育与生产劳动相结合"], "a": 3, "exp": "此题考查马克思主义关于人的全面发展学说。马克思主义关于人的全面发展学说的宗旨是人的劳动能力的全面发展，智力和体力的全面发展，还包括先天和后天的才能、志趣、道德、审美的充分发展。教育与生产劳动相结合是培养人的全面发展的唯一方法。因此，答案选D。", "type": "单选", "star": false, "src": {"book": "凯程应试题库", "ver": "26版", "page": 144}},
  {"id": "kc|edu-principle|ep-04|知识点二|14", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 14, "q": "马克思主义关于人的全面发展学说是在继承和发展历史上有关理论基础上的新的探索和科学概括。下列关于这一学说的说法，错误的是（　）", "opts": ["社会主义制度的建立为人的全面发展拓宽了道路", "马克思主义关于人的全面发展学说为我国教育目的的确立提供了依据", "人的全面发展是个性的充分发展，属于个人本位论", "追求人的全面发展与实现人的自由发展必须和谐统一"], "a": 2, "exp": "此题考查马克思主义关于人的全面发展学说。A、B、D选项说法正确。人的全面发展是个性的充分发展，强调个人发展与社会发展一致，这不属于个人本位论。此题为选非题，因此，答案选C。深联系微信1931637888", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 145}},
  {"id": "kc|edu-principle|ep-04|知识点二|15", "bank": "kc", "subj": "edu-principle", "ch": "ep-04", "chName": "第四章 教育目的与培养目标", "sec": "知识点二：教育目的的理论", "no": 15, "q": "我国新时代“五育”融合教育方针最能体现马克思主义关于人的全面发展学说的是（　）", "opts": ["人的多方面发展需有机结合", "人的发展要达到终极完美", "人的成长是自然进化的过程", "人的发展结果应完全一致"], "a": 0, "exp": "此题考查对马克思主义关于人的全面发展学说的理解。A.马克思主义关于人的全面发展学说主张人的体力和智力都得到充分的、自由的发展。我国新时代的教育方针将德智体美劳视为一个有机整体，促进学生全面发展，这与“人的多方面发展需有机结合”的内涵一致。√B.马克思主义强调人的全面发展是在实践中不断发展的，而非追求静态的“终极完美”。C.马克思主义强调人的全面发展是在社会实践中通过有意识的教育活动实现的，而非单纯“自然进化”。D.马克思主义强调人的全面发展是个性与共性的统一，而非抹杀多样性的“完全一致”。", "type": "单选", "star": true, "src": {"book": "凯程应试题库", "ver": "26版", "page": 145}}
]);
